  "general.languageFailed": "Não foi possível salvar o idioma. {error}",
  "computer.introLinux": "Cada bot tem seu próprio computador Linux — uma área de trabalho completa com navegador, terminal e seus próprios arquivos, separada de todos os outros bots e deste servidor. Os computadores dormem quando ficam parados e acordam quando precisam; nada neles se perde. Você pode assistir ou assumir o controle a qualquer momento.",
  "computer.introBrowser": "Cada bot tem seu próprio navegador neste servidor — uma janela privada que ele usa para abrir páginas, preencher formulários e ler o que está na tela. Você pode assistir ou assumir o controle a qualquer momento.",
  "computer.noneTitle": "Nenhum computador disponível",
  "computer.noneText": "Os bots ainda não têm tela neste servidor. Quem administra pode dar a cada bot um computador Linux (Docker mais a imagem de desktop) ou instalar um motor de navegador. Todo o resto continua funcionando.",
