  "computer.footLinux_one": "Apagar exclui esse computador com tudo o que foi instalado e salvo nele, exceto os arquivos da biblioteca do bot; um novo é criado na próxima vez. Só {n} computador pode ficar acordado por vez — o que está sem uso há mais tempo vai dormir.",
  "computer.footLinux_other": "Apagar exclui esse computador com tudo o que foi instalado e salvo nele, exceto os arquivos da biblioteca do bot; um novo é criado na próxima vez. Até {n} computadores podem ficar acordados ao mesmo tempo — o que está sem uso há mais tempo vai dormir.",
  "computer.footBrowser_one": "Redefinir fecha todas as páginas dessa área de trabalho e a recomeça do zero. Só {n} bot pode ter uma área de trabalho aberta por vez.",
  "computer.footBrowser_other": "Redefinir fecha todas as páginas dessa área de trabalho e a recomeça do zero. Até {n} bots podem ter uma área de trabalho aberta ao mesmo tempo.",
  "permissions.intro": "Decisões permanentes sobre o que seus bots podem fazer sem perguntar. Pagamentos e exclusões sempre perguntam, assim como, depois que um bot leu conteúdo externo, escrever para alguém que você nunca citou ou agir no seu próprio computador — seja o que for salvo aqui.",
  "permissions.emptyTitle": "Nenhuma permissão salva",
