  "egress.accountIntro": "Programas no computador de um bot podem chamar suas APIs sem nunca ter a chave: ative por bot (configurações do bot → Leitura e chaves). O Sklubot acrescenta a chave fora do computador, só para os hosts para os quais ela está salva, e te pergunta antes do primeiro uso de cada chave.",
  "egress.toggle": "Programas podem usar minhas chaves",
  "egress.intro": "Scripts e ferramentas que {name} roda no computador dele podem chamar APIs com seus segredos salvos, através do Sklubot. A chave nunca entra no computador; só os hosts de cada segredo funcionam; o primeiro uso de cada segredo, e mudanças depois de conteúdo externo, pedem sua confirmação.",
