  "smtp.title": "E-mails do servidor",
  "smtp.intro": "A conta de e-mail com a qual este Sklubot envia os próprios e-mails: links de “Esqueceu a senha?” e mudanças de endereço. Só você, o dono do servidor, vê isto.",
