  "smtp.brevo": "Servidor smtp-relay.brevo.com, STARTTLS, porta 587. Usuário e senha: o login SMTP e uma chave SMTP de Brevo → Settings → SMTP & API (uma chave SMTP, não uma chave de API). O remetente precisa ser um remetente validado na Brevo.",
  "smtp.ovh": "Servidor ssl0.ovh.net (ou smtp.mail.ovh.net), SSL/TLS, porta 465. Usuário e remetente = seu endereço de e-mail completo da OVH; senha = a senha dessa caixa de e-mail.",
