  "backup.title": "Backup automático",
  "backup.intro": "Toda noite, o próprio Sklubot envia uma cópia criptografada dos dados para um armazenamento S3 fora deste servidor (OVHcloud, Hetzner, Scaleway…). Só você (que administra o servidor) vê esta configuração.",
