  "backup.step1": "A chave de backup",
  "backup.keyWhy": "Os backups são criptografados antes de sair deste servidor. Aqui você cria uma chave em duas partes: a parte pública fica no servidor (só consegue criptografar), a parte privada fica com você (só ela consegue restaurar). Nem quem pegar o servidor ou o armazenamento consegue ler seus backups.",
