  "backup.docBucket": "Criar um bucket",
  "backup.docKeys": "Criar as chaves",
  "backup.guide.ovh.title": "Criar o bucket e as chaves na OVHcloud (pelo celular)",
  "backup.guide.ovh.1": "Painel da OVHcloud → Public Cloud → seu projeto → Storage → Object Storage.",
  "backup.guide.ovh.2": "Aba “Users”: crie um usuário de Object Storage. Anote a chave de acesso e a chave secreta (botão … → “View the secret key”).",
  "backup.guide.ovh.3": "Aba “Containers” → “Create an object container”: tipo “S3-compatible API”, um nome em minúsculas (ex.: sklubot-backups), uma região (ex.: Gravelines = gra), vincule o usuário e depois “Create”.",
  "backup.guide.ovh.4": "Aqui: escolha a mesma região, o nome do bucket, a chave de acesso e a chave secreta, e depois “Testar a conexão”.",
  "backup.guide.hetzner.title": "Criar o bucket e as chaves na Hetzner (pelo celular)",
  "backup.guide.hetzner.1": "Hetzner Console → seu projeto → Object Storage → “Create Bucket”: um local (ex.: Falkenstein = fsn1), um nome único, visibilidade “private”, e depois “Create & Buy now”.",
  "backup.guide.hetzner.2": "Menu “Security” → aba “S3 Credentials” → “Generate credentials”, com uma descrição (ex.: Sklubot).",
  "backup.guide.hetzner.3": "Copie na hora a chave de acesso (em cima) e a chave secreta (embaixo): a chave secreta não é mostrada de novo.",
  "backup.guide.hetzner.4": "Aqui: escolha o mesmo local, o nome do bucket e as duas chaves, e depois “Testar a conexão”.",
  "backup.guide.scaleway.title": "Criar o bucket e as chaves na Scaleway (pelo celular)",
  "backup.guide.scaleway.1": "Console da Scaleway → Object Storage → “+ Create bucket”: uma região (ex.: Paris = fr-par), um nome, visibilidade “Private”, e depois “Create bucket”.",
  "backup.guide.scaleway.2": "Menu da conta (canto superior direito) → “IAM & API keys” → aba “API keys” → “+ Generate API key”.",
  "backup.guide.scaleway.3": "Para o Object Storage, escolha o projeto do bucket como projeto preferido, e depois “Generate API key”. Copie a chave de acesso e a chave secreta (mostradas uma vez).",
  "backup.guide.scaleway.4": "Aqui: escolha a mesma região, o nome do bucket e as duas chaves, e depois “Testar a conexão”.",
  "backup.step3": "Quando, e quantos manter",
