  "backup.restore2": "No servidor, com SKLUBOT_S3_ENDPOINT, SKLUBOT_S3_REGION, SKLUBOT_S3_BUCKET, SKLUBOT_S3_PREFIX, SKLUBOT_S3_ACCESS_KEY e SKLUBOT_S3_SECRET_KEY definidos, este comando baixa o backup mais recente e o verifica:",
