  "caps.heading": "Limites de uso",
  "caps.intro": "Limites para o que você usa em um dia e em um mês, em dólares e/ou em tokens, para a conta toda ou para um bot (as tarefas em segundo plano dele contam junto). Dias e meses seguem seu fuso horário ({tz}, do seu perfil). Os limites de tokens também cobrem os turnos do Claude Code e do Codex, que não custam nada aqui.",
