  "grok.open": "Importar do Grok Bot",
  "grok.rowTitle": "Importar do Grok Bot",
  "grok.rowHint": "Traga os bots que você configurou no Grok Bot: copie um prompt lá, cole a resposta aqui, confira o que manter.",
