  "lp.trust.kicker": "Confiança",
  "lp.trust.title": "Feito para você confiar trabalho de verdade.",
  "lp.trust.t1t": "Contas separadas",
  "lp.trust.t1": "Cada conta só vê os próprios bots, arquivos e conversas. Os computadores dos bots são contêineres separados, em uma rede onde não conseguem se ver.",
  "lp.trust.t2t": "Segredos criptografados",
  "lp.trust.t2": "As conexões com apps e as senhas salvas são criptografadas no servidor (AES-256-GCM).",
  "lp.trust.t3t": "Software livre, hospedável na Europa",
  "lp.trust.t3": "O Sklubot é distribuído sob a licença MIT e roda no servidor que você escolher, na França ou em outro lugar da Europa.",
  "lp.trust.t4t": "Você continua no comando",
  "lp.trust.t4": "Um registro de cada ação, um botão de Pausa, limites de gastos, e seu sinal verde antes de qualquer coisa que não possa ser desfeita.",
  "lp.faq.kicker": "Perguntas",
  "lp.faq.title": "Perguntas que nos fazem.",
  "lp.faq.q1": "O que é um bot no Sklubot?",
  "lp.faq.a1": "Um assistente de IA com uma função, uma memória, ferramentas e, dependendo do plano, um computador. Você fala com ele como com um colega; ele também pode trabalhar sozinho, em uma rotina programada ou rumo a um objetivo.",
  "lp.faq.q2": "Um bot pode fazer besteira?",
  "lp.faq.a2": "Um bot novo é cuidadoso: pergunta antes de agir. Para qualquer coisa que não possa ser desfeita (enviar, pagar, excluir, publicar), ele para e espera o seu sinal verde, sem “sempre permitir”. Você pode pausá-lo a qualquer momento.",
  "lp.faq.q3": "Dá mesmo para falar com meus bots?",
  "lp.faq.a3": "Sim: ligue para um bot a partir da conversa e fale com ele em voz alta. Ele responde com a voz que você escolheu. Você também pode escrever para ele, quando quiser.",
  "lp.faq.q4": "Preciso instalar alguma coisa?",
  "lp.faq.a4": "Não: tudo funciona no navegador, no computador ou no celular. Se preferir, há um app para Windows e Linux, e um para Android.",
  "lp.faq.q5": "O Windows mostra um aviso quando instalo o app. É normal?",
  "lp.faq.a5": "Sim. O app ainda não tem assinatura, então o Windows SmartScreen mostra um aviso na primeira vez. Clique em “Mais informações” e depois em “Executar assim mesmo”. Você também pode usar o Sklubot online, sem instalar nada.",
  "lp.faq.q6": "Quais modelos de IA são usados?",
  "lp.faq.a6": "Os modelos de IA que este serviço oferece, ou sua própria chave de API, se preferir. Cada bot pode ter seu próprio modelo e modelos reserva.",
  "lp.faq.q7": "Onde ficam meus dados?",
  "lp.faq.a7": "No servidor deste serviço. Nas configurações você pode exportar seus dados ou excluir sua conta a qualquer momento.",
  "lp.faq.q8": "Por que confirmar meu endereço de e-mail?",
  "lp.faq.a8": "Para ter certeza de que é você mesmo, e para te ajudar se você esquecer a senha. Você pode explorar na hora; seus bots começam a trabalhar assim que ele for confirmado.",
  "lp.final.title": "Sua equipe está esperando.",
  "lp.final.sub": "Crie sua conta, escolha um modelo, passe uma primeira tarefa.",
  "lp.foot.tag": "Uma equipe de bots de IA, com sua memória, suas ferramentas, seu computador e sua voz.",
