  "onb.howHint": "Sua conta é grátis. Para pensar, seus bots usam sua própria conta de IA: conecte o OpenRouter, o ChatGPT ou o Claude. Você pode mudar quando quiser (Configurações → Minhas contas de IA).",
  "onb.howSub": "Minha assinatura do Claude ou do ChatGPT",
  "onb.howSubText": "Já tem Claude Pro/Max ou ChatGPT Plus/Pro? Entre no computador do seu bot: nada mais a pagar aqui.",
  "onb.howSubOff": "Não disponível neste serviço por enquanto.",
  "onb.howKey": "Minha chave de API",
